from rdkit import Chem
from rdkit.Chem import AllChem
rw=Chem.RWMol()
def atom(sym):
    return rw.AddAtom(Chem.Atom(sym))
def bond(i,j,t=Chem.BondType.SINGLE): rw.AddBond(i,j,t)
# Two cobalt centers, with the Co-Co bond shown in the drawing.
co_top=atom('Co'); co_bottom=atom('Co'); bond(co_top,co_bottom)
P=[atom('P') for _ in range(3)]
N=[atom('N') for _ in range(4)]
# Three iPr2P groups. Left and right P groups have CH2-N tethers;
# the central phosphine is P-N linked to the leftmost donor N.
for k,p in enumerate(P):
    for q in range(2):
        methine=atom('C'); bond(p,methine)
        bond(methine,atom('C')); bond(methine,atom('C'))
    if k==0:
        ch2=atom('C'); bond(p,ch2); bond(ch2,N[0])
    elif k==1:
        bond(p,N[0])
    else:
        ch2=atom('C'); bond(p,ch2); bond(ch2,N[2])
# Benzene rings: N1 and N3 each carry a phenyl group; N2/N4 are ortho on a benzene.
def benzene():
    r=[atom('C') for _ in range(6)]
    for i in range(6): bond(r[i],r[(i+1)%6],Chem.BondType.AROMATIC)
    for i in r: rw.GetAtomWithIdx(i).SetIsAromatic(True)
    for i in range(6): rw.GetBondBetweenAtoms(r[i],r[(i+1)%6]).SetIsAromatic(True)
    return r
ring_left=benzene(); bond(N[0],ring_left[0])
ring_right=benzene(); bond(N[2],ring_right[0])
ring_center=benzene(); bond(N[1],ring_center[0]); bond(N[3],ring_center[1])
# Metal coordination bonds (donor -> metal); these are dative, not covalent.
for p in P: bond(p,co_top,Chem.BondType.DATIVE)
for n in N: bond(n,co_bottom,Chem.BondType.DATIVE)
m=rw.GetMol(); Chem.SanitizeMol(m)
m=Chem.AddHs(m)
par=AllChem.ETKDGv3(); par.randomSeed=4652; par.maxIterations=1000
if AllChem.EmbedMolecule(m,par)<0: raise RuntimeError('3D embedding failed')
# ETKDG places all components relative to each other and gives realistic organic geometry.
AllChem.MolToXYZFile(m,'answer.xyz')
# replace comment for provenance
lines=open('answer.xyz').read().splitlines(); lines[1]='3D structure of the dicobalt complex depicted in mol_0097.png'
open('answer.xyz','w').write('\n'.join(lines)+'\n')
print('Wrote',len(lines)-2,'atoms')
